sys_script_include.script:
var MapperBase = Class.create();
MapperBase.prototype = {
    key: 'key',
    value: 'value',
    data: [],

    initialize: function(applicationName, dataSourceName, resolver, key, value) {
        if(key) this.key = key;
        if(value) this.value = value;
        this.data = this.fetch(applicationName, dataSourceName, resolver);
    },

	getData: function(){ return this.data; },

    fetch: function(applicationName, dataSourceName, resolver) {
        var data_source_sys_id = this.getDataSourceSysId(applicationName, dataSourceName);
        var data = this.getValues(data_source_sys_id);
		data = resolver.resolve(data);
        return data;
    },

    getDataSourceSysId: function(applicationName, dataSourceName) {
        var result = '';
        var gr = new GlideRecord("sys_data_source");
        gr.addQuery("sys_scope.name", applicationName);
        gr.addQuery("name", dataSourceName);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) result = gr.getValue("sys_id");
        return result;
    },

    // unstated assumption that the attachment is Excel
    getAttachmentSysId: function(dataSourceSysId) {
        var result = "";
        var gr = new GlideRecord("sys_attachment");
        gr.addQuery("table_name", "sys_data_source");
        gr.addQuery("table_sys_id", dataSourceSysId);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) result = gr.getValue("sys_id");
        return result;
    },

    getValues: function(dataSourceSysId) {
		var data = [];
        var attachment_sys_id = this.getAttachmentSysId(dataSourceSysId);
        var parser = new sn_impex.GlideExcelParser();
        var gsa = new GlideSysAttachment();
        var attachmentStream = gsa.getContentStream(attachment_sys_id);
        parser.parse(attachmentStream);

		// skip first row. Stop reading when key and value columns are empty.
		// Use JSON stringify to escape the key and value; note that this
		// returns the value enclosed in double quotes. Use slice to remove.
		parser.next();
        while (parser.next()) {
            var row = parser.getRow();
			var key = row[this.key];
			var value = row[this.value];
			if(!key && !value) break;
			data.push({
				"key":JSON.stringify(key).slice(1, -1),
				"value":JSON.stringify(value).slice(1, -1)
			});
        }
		return data;
    },

    type: 'MapperBase'
};
